.version 8.0
.target sm_80
.address_size 64

.visible .entry sigmoid_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 N
)
{
    .reg .pred   %p;
    .reg .b64    %rd1, %rd2, %rd3, %rd4, %rd5, %rd6;
    .reg .b32    %r1, %r2, %r3, %r4, %r5, %r6, %r7;
    .reg .f32    %f0, %f1, %f2, %f3, %f4, %f5, %f6, %f7, %f8;
    .reg .f16    %h0, %h1;

    // -----------------------------------------------------------------
    // Load kernel arguments
    // -----------------------------------------------------------------
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u64 %rd3, [N];

    // -----------------------------------------------------------------
    // Compute global thread index and stride
    // -----------------------------------------------------------------
    mov.u32 %r1, %tid.x;          // threadIdx.x
    mov.u32 %r2, %ctaid.x;        // blockIdx.x
    mov.u32 %r3, %ntid.x;         // blockDim.x
    mul.lo.u32 %r4, %r2, %r3;
    add.u32 %r5, %r4, %r1;        // linear thread id
    cvt.u64.u32 %rd4, %r5;        // idx (uint64)

    mov.u32 %r6, %nctaid.x;       // gridDim.x
    mul.lo.u32 %r7, %r6, %r3;     // blockDim.x * gridDim.x
    cvt.u64.u32 %rd5, %r7;        // stride (uint64)

    // -----------------------------------------------------------------
    // Load constants
    // -----------------------------------------------------------------
    mov.f32 %f6, 1.0;                                 // 1.0f
    mov.f32 %f7, -1.0;                                // -1.0f
    mov.f32 %f8, 1.4426950408889634;                  // log2(e)

LOOP:
    // while (idx < N)
    setp.ge.u64 %p, %rd4, %rd3;
    @%p bra DONE;

    // byte offset = idx * sizeof(half) (=2)
    mul.wide.u64 %rd6, %rd4, 2;

    // -----------------------------------------------------------------
    // Load half, convert to float, compute sigmoid, convert back
    // -----------------------------------------------------------------
    ld.global.u16 %h0, [%rd1 + %rd6];
    cvt.rn.f32.f16 %f0, %h0;                 // float x

    // sigmoid: y = 1 / (1 + exp(-x))
    mul.f32 %f1, %f0, %f7;                   // -x
    mul.f32 %f2, %f1, %f8;                   // -x * log2(e)
    ex2.approx.f32 %f3, %f2;                // 2^{...} ≈ exp(-x)
    add.f32 %f4, %f3, %f6;                  // 1 + exp(-x)
    rcp.approx.f32 %f5, %f4;                // 1/(1+exp(-x))

    cvt.rn.f16.f32 %h1, %f5;                // back to half
    st.global.u16 [%rd2 + %rd6], %h1;       // store result

    // -----------------------------------------------------------------
    // Advance idx by stride
    // -----------------------------------------------------------------
    add.u64 %rd4, %rd4, %rd5;
    bra LOOP;

DONE:
    ret;
}
"""

